create definer = root@`%` view vw_associado as
select distinct `m`.`id_membro`        AS `id_membro`,
                `p`.`id_pessoa`        AS `id_pessoa`,
                `p`.`emailPrincipal`   AS `emailPrincipal`,
                `p`.`nome`             AS `nome`,
                `p`.`pessoaAdmin`      AS `pessoaAdmin`,
                `p`.`senha`            AS `senha`,
                `p`.`celularPrincipal` AS `celularPrincipal`,
                `p`.`dataNascimento`   AS `dataNascimento`,
                `p`.`cpf`              AS `cpf`,
                `e`.`sigla`            AS `sigla`,
                `r`.`tag_uf`           AS `uf_res`,
                `c`.`tag_uf`           AS `uf_com`
from ((((`asa_production`.`membro` `m` left join `asa_production`.`pessoa` `p`
         on (`p`.`id_pessoa` = `m`.`id_pessoa`)) left join `asa_production`.`pessoa` `e`
        on (`e`.`id_pessoa` = `m`.`id_pessoa_empresa`)) left join `asa_production`.`endereco` `r`
       on (`r`.`id_endereco` = `p`.`id_endereco_residencial`)) left join `asa_production`.`endereco` `c`
      on (`c`.`id_endereco` = `p`.`id_endereco_comercial`))
where 1
  and `m`.`active` = 1
  and `p`.`active` = 1
  and `e`.`active` = 1
  and `m`.`id_perfil` = 17;

-- comment on column vw_associado.emailPrincipal not supported: E-mail principal

-- comment on column vw_associado.nome not supported: Nome

-- comment on column vw_associado.pessoaAdmin not supported: Flag indicando que pessoa é administrador

-- comment on column vw_associado.celularPrincipal not supported: Celular

-- comment on column vw_associado.dataNascimento not supported: Data nascimento

-- comment on column vw_associado.cpf not supported: CPF

-- comment on column vw_associado.sigla not supported: Sigla

-- comment on column vw_associado.uf_res not supported: Estado

-- comment on column vw_associado.uf_com not supported: Estado

create definer = root@`%` view vw_associado_news as
select distinct `m`.`id_membro`        AS `id_membro`,
                `p`.`id_pessoa`        AS `id_pessoa`,
                `p`.`emailPrincipal`   AS `emailprincipal`,
                `p`.`nome`             AS `nome`,
                `p`.`pessoaAdmin`      AS `pessoaadmin`,
                `p`.`senha`            AS `senha`,
                `p`.`celularPrincipal` AS `celularprincipal`,
                `p`.`dataNascimento`   AS `datanascimento`,
                `p`.`cpf`              AS `cpf`,
                `e`.`sigla`            AS `sigla`,
                `r`.`tag_uf`           AS `uf_res`,
                `c`.`tag_uf`           AS `uf_com`,
                `m`.`insertDate`       AS `insertdate`
from ((((`asa_production`.`membro` `m` left join `asa_production`.`pessoa` `p`
         on (`p`.`id_pessoa` = `m`.`id_pessoa`)) left join `asa_production`.`pessoa` `e`
        on (`e`.`id_pessoa` = `m`.`id_pessoa_empresa`)) left join `asa_production`.`endereco` `r`
       on (`r`.`id_endereco` = `p`.`id_endereco_residencial`)) left join `asa_production`.`endereco` `c`
      on (`c`.`id_endereco` = `p`.`id_endereco_comercial`))
where 1
  and `m`.`active` = 1
  and `p`.`active` = 1
  and `e`.`active` = 1
  and ifnull(`p`.`emailPrincipal`, '') <> ''
  and ifnull(`p`.`flagNaoEnviarEmail`, 0) = 0
  and `m`.`id_perfil` = 17
  and !(`p`.`emailPrincipal` in (select distinct `vw_sender_invalid`.`email` from `mailer`.`vw_sender_invalid`))
  and !(`p`.`emailPrincipal` in (select distinct `mailer`.`mail_blacklist`.`email` from `mailer`.`mail_blacklist`))
  and !(`p`.`emailPrincipal` in (select distinct `mailer`.`smtp2go`.`recipient`
                                 from `mailer`.`smtp2go`
                                 where 1
                                   and `mailer`.`smtp2go`.`event_type` not in ('Delivered', 'Processed')));

