create definer = root@`%` view vw_member_mail_queue as
select distinct `m`.`id_membro`        AS `member_id`,
                `p`.`id_pessoa`        AS `person_id`,
                `p`.`emailPrincipal`   AS `email`,
                `p`.`nome`             AS `name`,
                `p`.`pessoaAdmin`      AS `isAdmin`,
                `p`.`senha`            AS `password`,
                `p`.`celularPrincipal` AS `phone`,
                `p`.`dataNascimento`   AS `birthdate`,
                `p`.`cpf`              AS `br_cpf`,
                `e`.`sigla`            AS `company`,
                `r`.`tag_uf`           AS `home_uf`,
                `c`.`tag_uf`           AS `work_uf`
from ((((`asa_production`.`membro` `m` left join `asa_production`.`pessoa` `p`
         on (`p`.`id_pessoa` = `m`.`id_pessoa`)) left join `asa_production`.`pessoa` `e`
        on (`e`.`id_pessoa` = `m`.`id_pessoa_empresa`)) left join `asa_production`.`endereco` `r`
       on (`r`.`id_endereco` = `p`.`id_endereco_residencial`)) left join `asa_production`.`endereco` `c`
      on (`c`.`id_endereco` = `p`.`id_endereco_comercial`))
where 1
  and `m`.`active` = 1
  and `p`.`active` = 1
  and `e`.`active` = 1
  and ifnull(`p`.`emailPrincipal`, '') <> ''
  and ifnull(`p`.`flagNaoEnviarEmail`, 0) = 0
  and `m`.`id_perfil` = 17;

