create definer = root@`%` view vw_membro as
select distinct `m`.`id_membro`                                      AS `id_membro`,
                `m`.`id_perfil`                                      AS `id_perfil`,
                `m`.`insertDate`                                     AS `insertdate`,
                `m`.`updateDate`                                     AS `updatedate`,
                case
                    when `m`.`id_perfil` = 4 then 'entity'
                    when `m`.`id_perfil` = 17 then 'associate'
                    when `m`.`id_perfil` = 32 then 'entity_view' end AS `type`,
                `p`.`id_pessoa`                                      AS `id_pessoa`,
                `p`.`emailPrincipal`                                 AS `emailprincipal`,
                `p`.`nome`                                           AS `nome`,
                `p`.`pessoaAdmin`                                    AS `pessoaadmin`,
                `p`.`senha`                                          AS `senha`,
                `p`.`celularPrincipal`                               AS `celularprincipal`,
                `p`.`dataNascimento`                                 AS `datanascimento`,
                `p`.`cpf`                                            AS `cpf`,
                `e`.`sigla`                                          AS `sigla`,
                `r`.`tag_uf`                                         AS `uf_res`,
                `c`.`tag_uf`                                         AS `uf_com`
from ((((`asa_production`.`membro` `m` left join `asa_production`.`pessoa` `p`
         on (`p`.`id_pessoa` = `m`.`id_pessoa`)) left join `asa_production`.`pessoa` `e`
        on (`e`.`id_pessoa` = `m`.`id_pessoa_empresa`)) left join `asa_production`.`endereco` `r`
       on (`r`.`id_endereco` = `p`.`id_endereco_residencial`)) left join `asa_production`.`endereco` `c`
      on (`c`.`id_endereco` = `p`.`id_endereco_comercial`))
where 1
  and `m`.`active` = 1
  and `p`.`active` = 1
  and `e`.`active` = 1;

-- comment on column vw_membro.emailprincipal not supported: E-mail principal

-- comment on column vw_membro.nome not supported: Nome

-- comment on column vw_membro.pessoaadmin not supported: Flag indicando que pessoa é administrador

-- comment on column vw_membro.celularprincipal not supported: Celular

-- comment on column vw_membro.datanascimento not supported: Data nascimento

-- comment on column vw_membro.cpf not supported: CPF

-- comment on column vw_membro.sigla not supported: Sigla

-- comment on column vw_membro.uf_res not supported: Estado

-- comment on column vw_membro.uf_com not supported: Estado

create definer = root@`%` view vw_membro_apex as
select distinct `m`.`id_membro`             AS `id_membro`,
                `p`.`id_pessoa`             AS `id_pessoa`,
                `m`.`id_pessoa_empresa`     AS `id_pessoa_empresa`,
                `m`.`id_perfil`             AS `old_id_perfil`,
                `l`.`nome`                  AS `old_nome_perfil`,
                `m`.`active`                AS `membro_active`,
                `p`.`active`                AS `pessoa_active`,
                `l`.`active`                AS `perfil_active`,
                ucase(`e`.`sigla`)          AS `sigla`,
                case
                    when `m`.`id_perfil` = 1 then 'admin'
                    when `m`.`id_perfil` = 3 then 'partner_company'
                    when `m`.`id_perfil` = 4 then 'staff'
                    when `m`.`id_perfil` = 13 then 'customer_support'
                    when `m`.`id_perfil` = 14 then 'marketing'
                    when `m`.`id_perfil` = 15 then 'agreement_analyst'
                    when `m`.`id_perfil` = 17 then 'associate'
                    when `m`.`id_perfil` = 18 then 'vip_lounge_service'
                    when `m`.`id_perfil` = 20 then 'temporary_access'
                    when `m`.`id_perfil` = 30 then 'dependent'
                    when `m`.`id_perfil` = 32 then 'staff_view'
                    else '' end             AS `perfil_code`,
                ucase(`p`.`nome`)           AS `nome`,
                ucase(`p`.`sobrenome`)      AS `sobrenome`,
                lcase(`p`.`emailPrincipal`) AS `emailprincipal`,
                `p`.`dataNascimento`        AS `datanascimento`,
                `r`.`id_endereco`           AS `id_endereco_residencial`,
                `r`.`tag_uf`                AS `uf_residencial`,
                `r`.`logradouro`            AS `logradouro_residencial`,
                `c`.`id_endereco`           AS `id_endereco_comercial`,
                `c`.`tag_uf`                AS `uf_comercial`,
                `c`.`logradouro`            AS `logradouro_comercial`,
                `p`.`senha`                 AS `senha`,
                `p`.`cpf`                   AS `cpf`,
                `p`.`cnpj`                  AS `cnpj`,
                `p`.`celularPrincipal`      AS `celularprincipal`,
                `es`.`id_entidadeServidor`  AS `id_entidadeservidor`,
                `es`.`active`               AS `active`
from ((((((`asa_production`.`membro` `m` left join `asa_production`.`perfil` `l`
           on (`l`.`id_perfil` = `m`.`id_perfil`)) left join `asa_production`.`pessoa` `p`
          on (`p`.`id_pessoa` = `m`.`id_pessoa`)) left join `asa_production`.`pessoa` `e`
         on (`e`.`id_pessoa` = `m`.`id_pessoa_empresa`)) left join `asa_production`.`endereco` `r`
        on (`r`.`id_endereco` = `p`.`id_endereco_residencial`)) left join `asa_production`.`endereco` `c`
       on (`c`.`id_endereco` = `p`.`id_endereco_comercial`)) left join `asa_production`.`entidade_servidor` `es`
      on (`es`.`id_pessoa_empresa` = `e`.`id_pessoa`))
where 1
  and `m`.`active` = 1
  and `l`.`active` = 1
  and `p`.`active` = 1
  and `e`.`active` = 1
  and `es`.`active` = 1
order by ucase(`e`.`sigla`),
         case
             when `m`.`id_perfil` = 1 then 'admin'
             when `m`.`id_perfil` = 3 then 'partner_company'
             when `m`.`id_perfil` = 4 then 'staff'
             when `m`.`id_perfil` = 13 then 'customer_support'
             when `m`.`id_perfil` = 14 then 'marketing'
             when `m`.`id_perfil` = 15 then 'agreement_analyst'
             when `m`.`id_perfil` = 17 then 'associate'
             when `m`.`id_perfil` = 18 then 'vip_lounge_service'
             when `m`.`id_perfil` = 20 then 'temporary_access'
             when `m`.`id_perfil` = 30 then 'dependent'
             when `m`.`id_perfil` = 32 then 'staff_view'
             else '' end, `p`.`nome`;

-- comment on column vw_membro_apex.old_nome_perfil not supported: Nome

-- comment on column vw_membro_apex.datanascimento not supported: Data nascimento

-- comment on column vw_membro_apex.uf_residencial not supported: Estado

-- comment on column vw_membro_apex.logradouro_residencial not supported: Logradouro

-- comment on column vw_membro_apex.uf_comercial not supported: Estado

-- comment on column vw_membro_apex.logradouro_comercial not supported: Logradouro

-- comment on column vw_membro_apex.cpf not supported: CPF

-- comment on column vw_membro_apex.cnpj not supported: CNPJ

-- comment on column vw_membro_apex.celularprincipal not supported: Celular

create definer = root@`%` view vw_sender_invalid as
select `asa_production`.`sender`.`email`                      AS `email`,
       `asa_production`.`sender`.`groups`                     AS `groups`,
       `asa_production`.`sender`.`phone`                      AS `phone`,
       `asa_production`.`sender`.`email_status`               AS `email_status`,
       `asa_production`.`sender`.`sms_status`                 AS `sms_status`,
       `asa_production`.`sender`.`transactional_email_status` AS `transactional_email_status`,
       `asa_production`.`sender`.`transactional_sms_status`   AS `transactional_sms_status`,
       `asa_production`.`sender`.`location`                   AS `location`,
       `asa_production`.`sender`.`created`                    AS `created`,
       `asa_production`.`sender`.`last_name`                  AS `last_name`,
       `asa_production`.`sender`.`first_name`                 AS `first_name`,
       `asa_production`.`sender`.`idade`                      AS `idade`,
       `asa_production`.`sender`.`senha`                      AS `senha`,
       `asa_production`.`sender`.`entidade`                   AS `entidade`,
       `asa_production`.`sender`.`unidade_federação__uf_`     AS `unidade_federação__uf_`,
       `asa_production`.`sender`.`id_membro`                  AS `id_membro`,
       `asa_production`.`sender`.`data_nascimento`            AS `data_nascimento`,
       `asa_production`.`sender`.`id_pessoa`                  AS `id_pessoa`,
       `asa_production`.`sender`.`cpf`                        AS `cpf`
from `asa_production`.`sender`
where 1 = 1
  and `asa_production`.`sender`.`email_status` <> 'active'
  and `asa_production`.`sender`.`transactional_email_status` <> 'active'
order by `asa_production`.`sender`.`email`;

